let lang='tr';const listeners=[],warned=new Set(),formats={};
function store(){try{return typeof localStorage!=='undefined'?localStorage:null;}catch{return null;}}
function detect(){try{const q=typeof location!=='undefined'&&new URLSearchParams(location.search).get('lang');if(LANGS.includes(q))return q;}catch{}try{const v=store()?.getItem(KEY);if(LANGS.includes(v))return v;const old=store()?.getItem('kervan_language_v1');/* RC10 game's choice on updated installs */if(LANGS.includes(old))return old;}catch{}const nav=typeof navigator!=='undefined'?(navigator.languages?.[0]||navigator.language||''):'';return /^tr\b/i.test(nav)?'tr':'en';}
function set(next,persist=true){if(!LANGS.includes(next))return;lang=next;if(persist)try{store()?.setItem(KEY,next);}catch{}if(typeof document!=='undefined')document.documentElement.lang=next;for(const fn of listeners)fn(next);}
function t(key,vars={}){let v=T[lang][key];if(v===undefined){v=T.tr[key];if(!warned.has(key)){warned.add(key);if(typeof console!=='undefined')console.warn('Missing text:',lang,key);}}if(v===undefined)return key;return typeof v==='function'?v(vars):v.replace(/\{(\w+)\}/g,(m,k)=>k in vars?vars[k]:m);}
function name(tr){return lang==='tr'?tr:NAMES[tr]||tr;}
// Locale-aware numbers: Turkish 1.250,5 · English 1,250.5.
function n(value,digits=0){const k=lang+digits;formats[k]=formats[k]||new Intl.NumberFormat(lang==='tr'?'tr-TR':'en-US',{maximumFractionDigits:digits});return formats[k].format(value);}
const int=value=>n(Math.floor(value));
// Short large numbers from 10,000 up: 12.4K / 3.1M (TR: 12,4B bin, 3,1Mn milyon, Mr milyar, Tn trilyon), then aa, ab, ...
const SUFFIX={tr:['','B','Mn','Mr','Tn'],en:['','K','M','B','T']};
function money(value,digits=0){const a=Math.abs(value);if(!(a>=1e4))return n(digits?value:Math.floor(value),digits);const e=Math.floor(Math.log10(a)/3),s=SUFFIX[lang],k=e-s.length;
 const suffix=e<s.length?s[e]:String.fromCharCode(97+Math.floor(k/26)%26)+String.fromCharCode(97+k%26),m=value/Math.pow(1000,e),d=Math.abs(m)>=100?0:Math.abs(m)>=10?1:2;return n(Math.floor(m*10**d)/10**d,d)+suffix;}
return {LANGS,T,NAMES,get lang(){return lang;},detect,set,t,name,n,int,money,onChange:fn=>listeners.push(fn),init(){set(detect(),false);}};
